    11→@MainActor
    12→struct TimelineItemMenuActionProvider {
    13→    let timelineItem: RoomTimelineItemProtocol
    14→    let canCurrentUserSendMessage: Bool
    15→    let canCurrentUserRedactSelf: Bool
    16→    let canCurrentUserRedactOthers: Bool
    17→    let canCurrentUserPin: Bool
    18→    let pinnedEventIDs: Set<String>
    19→    let isDM: Bool
    20→    let isViewSourceEnabled: Bool
    21→    let areThreadsEnabled: Bool
    22→    let timelineKind: TimelineKind
    23→    let emojiProvider: EmojiProviderProtocol
    24→    
    25→    // swiftlint:disable:next cyclomatic_complexity
    26→    func makeActions() -> TimelineItemMenuActions? {
    27→        guard let item = timelineItem as? EventBasedTimelineItemProtocol else {
    28→            // Don't show a context menu for non-event based items.
    29→            return nil
    30→        }
    31→
    32→        if timelineItem is StateRoomTimelineItem {
    33→            // Don't show a context menu for state events.
    34→            return nil
    35→        }
    36→
    37→        if let encryptedItem = timelineItem as? EncryptedRoomTimelineItem {
    38→            return makeEncryptedItemActions(encryptedItem)
    39→        }
    40→        
    41→        var actions: [TimelineItemMenuAction] = []
    42→        var secondaryActions: [TimelineItemMenuAction] = []
    43→        
    44→        if timelineKind == .pinned || timelineKind == .media(.mediaFilesScreen) || timelineKind == .media(.pinnedEventsScreen) {
    45→            actions.append(.viewInRoomTimeline)
    46→        }
    47→        
    48→        if canRedactItem(item), let poll = item.pollIfAvailable, !poll.hasEnded, let eventID = item.id.eventID {
    49→            actions.append(.endPoll(pollStartID: eventID))
    50→        }
    51→
    52→        if item.canBeRepliedTo, canCurrentUserSendMessage {
    53→            if let messageItem = item as? EventBasedMessageTimelineItemProtocol {
    54→                // If threads are enabled we will have the dedicated `replyInThread` action
    55→                // so there is no need to make the normal reply use the thread.
    56→                actions.append(.reply(isThread: areThreadsEnabled ? false : messageItem.properties.isThreaded))
    57→            } else {
    58→                actions.append(.reply(isThread: false))
    59→            }
    60→            
    61→            if areThreadsEnabled, !timelineKind.isThread {
    62→                actions.append(.replyInThread)
    63→            }
    64→        }
    65→        
    66→        if item.isForwardable {
    67→            actions.append(.forward(itemID: item.id))
    68→        }
    69→        
    70→        if item.isEditable, canCurrentUserSendMessage {
    71→            if item.supportsMediaCaption {
    72→                if item.hasMediaCaption {
    73→                    actions.append(.editCaption)
    74→                } else {
    75→                    actions.append(.addCaption)
    76→                }
    77→            } else if item is PollRoomTimelineItem {
    78→                actions.append(.editPoll)
    79→            } else if !(item is VoiceMessageRoomTimelineItem) {
    80→                actions.append(.edit)
    81→            }
    82→        }
    83→        
    84→        if item.isRemoteMessage {
    85→            actions.append(.copyPermalink)
    86→        }
    87→        
    88→        if canCurrentUserPin, let eventID = item.id.eventID {
    89→            actions.append(pinnedEventIDs.contains(eventID) ? .unpin : .pin)
    90→        }
    91→
    92→        if item.isCopyable {
    93→            actions.append(.copy)
    94→            
    95→            if !ProcessInfo.processInfo.isiOSAppOnMac {
    96→                // As of macOS 26.2, the sheet isn't presented, but it is easy enough
    97→                // to select some text and right click on Mac anyway so hide this one.
    98→                actions.append(.translate)
    99→            }
   100→        } else if item.hasMediaCaption {
   101→            actions.append(.copyCaption)
   102→        }
   103→        
   104→        if item.isEditable, item.hasMediaCaption {
   105→            actions.append(.removeCaption)
   106→        }
   107→        
   108→        if isViewSourceEnabled {
   109→            actions.append(.viewSource)
   110→        }
   111→        
   112→        if !item.isOutgoing {
   113→            secondaryActions.append(.report)
   114→        }
   115→        
   116→        if canRedactItem(item) {
   117→            secondaryActions.append(.redact)
   118→        }
   119→        
   120→        switch timelineKind {
   121→        case .pinned:
   122→            actions = actions.filter(\.canAppearInPinnedEventsTimeline)
   123→            secondaryActions = secondaryActions.filter(\.canAppearInPinnedEventsTimeline)
   124→        case .media:
   125→            actions.append(.share)
   126→            actions.append(.save)
   127→            actions = actions.filter(\.canAppearInMediaDetails)
   128→            secondaryActions = secondaryActions.filter(\.canAppearInMediaDetails)
   129→        case .live, .detached, .thread:
   130→            break // viewInRoomTimeline is the only non-room item and was added conditionally.
   131→        }
   132→        
   133→        if item.hasFailedToSend {
   134→            actions = actions.filter(\.canAppearInFailedEcho)
   135→            secondaryActions = secondaryActions.filter(\.canAppearInFailedEcho)
   136→        }
   137→        
   138→        if item.isRedacted {
   139→            actions = actions.filter(\.canAppearInRedacted)
   140→            secondaryActions = secondaryActions.filter(\.canAppearInRedacted)
   141→        }
   142→        
   143→        let isReactable = timelineKind == .live || timelineKind == .detached || timelineKind.isThread ? item.isReactable : false
   144→
   145→        return .init(isReactable: isReactable, actions: actions, secondaryActions: secondaryActions, emojiProvider: emojiProvider)
   146→    }
   147→    
   148→    private func makeEncryptedItemActions(_ encryptedItem: EncryptedRoomTimelineItem) -> TimelineItemMenuActions? {
   149→        var actions: [TimelineItemMenuAction] = [.copyPermalink]
   150→
   151→        if isViewSourceEnabled {
   152→            actions.append(.viewSource)
   153→        }
   154→                
   155→        return .init(isReactable: false,
   156→                     actions: actions,
   157→                     secondaryActions: [],
   158→                     emojiProvider: emojiProvider)
   159→    }
   160→    
   161→    private func canRedactItem(_ item: EventBasedTimelineItemProtocol) -> Bool {
   162→        item.isOutgoing ? canCurrentUserRedactSelf : canCurrentUserRedactOthers && !isDM
   163→    }
   164→}
